class Reactive { static components = new Map(); static init() { document.querySelectorAll('[data-reactive]').forEach(el => { const component = new ReactiveComponent(el); this.components.set(component.id, component); }); } static async sendAction(componentId, action, data = {}) { const component = this.components.get(componentId); if (!component) { console.error(`Component ${componentId} not found`); return; } try { const response = await fetch('/__reactive', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Requested-With': 'XMLHttpRequest', 'Accept': 'application/json' }, body: JSON.stringify({ __component_name: componentId, __component_action: action, __component_states: component.getStates(), ...data }) }); if (!response.ok) { throw new Error(`HTTP error! status: ${response.status}`); } const responseData = await response.json(); component.update(responseData.html, responseData.state); } catch (error) { console.error('Error sending reactive action:', error); } } } class ReactiveComponent { constructor(el) { this.el = el; this.id = el.dataset.reactiveName; this.state = this.parseState(el.dataset.reactiveState); this._pendingFocus = null; this.bindEvents(); } parseState(stateString) { try { return stateString ? JSON.parse(stateString) : {}; } catch (e) { console.error('Error parsing state:', e); return {}; } } getStates() { return this.state; } bindEvents() { this.el.querySelectorAll('[data-action]').forEach(btn => { btn._hasReactiveBinding = btn._hasReactiveBinding || false; if (!btn._hasReactiveBinding) { btn.addEventListener('click', (e) => { e.preventDefault(); const action = btn.dataset.action; const params = btn.dataset.params ? JSON.parse(btn.dataset.params) : {}; Reactive.sendAction(this.id, action, params); }); btn._hasReactiveBinding = true; } }); this.el.querySelectorAll('[data-onchange]').forEach(input => { input._hasReactiveBinding = input._hasReactiveBinding || false; if (!input._hasReactiveBinding) { const inputTypes = { value: ['text', 'number', 'email', 'password', 'search', 'tel', 'url', 'textarea', 'select-one'], checked: ['checkbox', 'radio'], }; const action = input.dataset.onchange; const attribute = input.dataset.attribute || 'value'; const debounce = (func, delay) => { let timeoutId; return (...args) => { clearTimeout(timeoutId); timeoutId = setTimeout(() => func.apply(this, args), delay); }; }; const handleInputEvent = (e) => { const params = {}; const type = input.type.toLowerCase(); const tagName = input.tagName.toLowerCase(); if (inputTypes.checked.includes(type)) { params[attribute] = input.checked; if (type === 'radio' && input.checked) { params[attribute] = input.value; } } else if (tagName === 'select' || inputTypes.value.includes(type)) { params[attribute] = input.value; } else { params[attribute] = input.dataset[attribute] || input.getAttribute(attribute); } this._pendingFocus = { id: input.id, name: input.name, tagName: input.tagName, type: input.type, value: input.value, selectionStart: input.selectionStart, selectionEnd: input.selectionEnd, cursorPosition: this.getCursorPosition(input) }; Reactive.sendAction(this.id, action, params); }; /** * input.addEventListener('input', (e) => { * if (this._pendingFocus && this._pendingFocus.id === input.id) { * this._pendingFocus.cursorPosition = this.getCursorPosition(input); * this._pendingFocus.value = input.value; * } * }); */ const debouncedHandler = debounce(handleInputEvent, 200); if (inputTypes.checked.includes(input.type.toLowerCase())) { input.addEventListener('change', handleInputEvent); } else { input.addEventListener('input', debouncedHandler); input.addEventListener('change', handleInputEvent); } input._hasReactiveBinding = true; } }); } async update(html, state = {}) { const activeElement = document.activeElement; if (activeElement && this.el.contains(activeElement)) { this._pendingFocus = { id: activeElement.id, name: activeElement.name, tagName: activeElement.tagName, type: activeElement.type, value: activeElement.value, selectionStart: activeElement.selectionStart, selectionEnd: activeElement.selectionEnd, componentId: this.id }; } if (state) { this.state = state; this.el.dataset.reactiveState = JSON.stringify(state); } const parser = new DOMParser(); const doc = parser.parseFromString(html, 'text/html'); const newInner = doc.body.firstElementChild; if (newInner) { this.el.innerHTML = newInner.innerHTML; } else { this.el.innerHTML = html; } const scrollTop = this.el.scrollTop; this.el.scrollTop = scrollTop; this.bindEvents(); if (this._pendingFocus) { await new Promise(resolve => setTimeout(resolve, 50)); this.restoreFocus(); } } getCursorPosition(element) { if (!element) return null; if (element.isContentEditable) { const selection = window.getSelection(); if (selection.rangeCount > 0) { const range = selection.getRangeAt(0); return { type: 'contenteditable', range: range.cloneRange() }; } return null; } return { type: 'input', start: element.selectionStart, end: element.selectionEnd, direction: element.selectionDirection }; } restoreFocus() { if (!this._pendingFocus) return; if (this._pendingFocus.componentId && this._pendingFocus.componentId !== this.id) { console.debug('Focus belongs to different component, skipping'); this._pendingFocus = null; return; } const { id, name, tagName, type, value, selectionStart, selectionEnd } = this._pendingFocus; let elementToFocus = null; const searchRoot = this.el; if (id) { elementToFocus = searchRoot.querySelector(`#${id}`); } if (!elementToFocus && name) { const candidates = searchRoot.querySelectorAll(`${tagName}[name="${name}"]`); if (candidates.length > 0) { if (type === 'radio') { elementToFocus = Array.from(candidates).find(el => el.value === value) || candidates[0]; } else { elementToFocus = candidates[0]; } } } if (!elementToFocus && tagName) { const candidates = searchRoot.querySelectorAll(tagName); if (candidates.length > 0) { elementToFocus = candidates[0]; } } if (elementToFocus) { if (this.el.contains(elementToFocus)) { elementToFocus.focus(); if (value !== undefined && elementToFocus.value !== value) { elementToFocus.value = value; } if (typeof selectionStart === 'number' && typeof selectionEnd === 'number' && elementToFocus.setSelectionRange) { try { elementToFocus.setSelectionRange(selectionStart, selectionEnd); } catch (e) { console.debug('Could not restore selection range', e); } } } else { console.warn('Attempted to focus element outside component', elementToFocus); } } this._pendingFocus = null; } }